mapper.update:
MERGE INTO SJT0TG t
USING DUAL
   ON (t.corp_gr = #{corpGr} AND t.ymd = TO_DATE(REPLACE(#{ymd}, '-', ''), 'YYYYMMDD') AND t.koscom_cd = #{koscomCd})
WHEN MATCHED THEN
    UPDATE SET
        t.close      = #{close, jdbcType=NUMERIC}
      , t.volume     = #{volume, jdbcType=NUMERIC}
      , t.value      = #{value, jdbcType=NUMERIC}
      , t.preclose   = #{preclose, jdbcType=NUMERIC}
      , t.change     = NVL(#{change, jdbcType=NUMERIC}, #{close, jdbcType=NUMERIC} - #{preclose, jdbcType=NUMERIC})
      , t.aekm       = #{aekm, jdbcType=NUMERIC}
      , t.sangj_jusu = #{sangjJusu, jdbcType=NUMERIC}
      , t.mod_dt     = SYSDATE
WHEN NOT MATCHED THEN
    INSERT (
        corp_gr, ymd, koscom_cd, close, volume, value, preclose, change, aekm, sangj_jusu, mod_dt
    ) VALUES (
        #{corpGr}
      , TO_DATE(REPLACE(#{ymd}, '-', ''), 'YYYYMMDD')
      , #{koscomCd}
      , #{close, jdbcType=NUMERIC}
      , #{volume, jdbcType=NUMERIC}
      , #{value, jdbcType=NUMERIC}
      , #{preclose, jdbcType=NUMERIC}
      , NVL(#{change, jdbcType=NUMERIC}, #{close, jdbcType=NUMERIC} - #{preclose, jdbcType=NUMERIC})
      , #{aekm, jdbcType=NUMERIC}
      , #{sangjJusu, jdbcType=NUMERIC}
      , SYSDATE
    )
